/*
 * KickPi K7 (RK3576) AMP firmware FIT source.
 *
 * amp3: firmware for cpu3 (Cortex-A53, MPIDR 0x3), loaded at 0x41800000 and
 * started by U-Boot (CONFIG_ROCKCHIP_AMP) via PSCI CPU_ON before Linux boots.
 *
 * Phase 1: prebuilt bare-metal bin (amp-baremetal/), copied to output/rtt3.bin.
 *
 * The linux{} node moves kernel_addr_r to 0x42000000 so the decompressed
 * kernel cannot overwrite the 0x41800000+8MB AMP region.
 */

/dts-v1/;
/ {
	description = "KickPi K7 AMP: RTOS on cpu3";
	#address-cells = <1>;

	images {
		amp3 {
			description = "rtt3";
			data = /incbin/("rtt3.bin");
			type = "firmware";
			compression = "none";
			arch = "arm64";
			cpu = <0x3>;		/* MPIDR: A53 cluster0 core3 */
			thumb = <0>;
			hyp = <1>;		/* arm64+hyp = default PE state: pure PSCI CPU_ON, no SIP dependency */
			load = <0x41800000>;
			size = <0x800000>;
			udelay = <10000>;
			/* build-time only (stripped): ./build.sh amp compiles the
			 * RT-Thread bsp at rtos/bsp/rockchip/rk3576-k7-amp and drops
			 * output/rtt3.bin; remove this node to pack a prebuilt bin
			 * (e.g. amp-baremetal) instead. */
			hash {
				algo = "sha256";
			};
		};
	};

	/* build-time only, stripped before mkimage */

	configurations {
		default = "conf";
		conf {
			description = "Rockchip AMP images";
			rollback-index = <0x0>;
			loadables = "amp3";
			signature {
				algo = "sha256,rsa2048";
				padding = "pss";
				key-name-hint = "dev";
				sign-images = "loadables";
			};
			/*
			 * Linux stays on cpu0 (boot cpu). U-Boot reads load/load_c
			 * here and env_set's kernel_addr_r / kernel_addr_c.
			 */
			linux {
				description = "linux-os";
				arch = "arm64";
				cpu = <0x0>;
				thumb = <0>;
				hyp = <0>;
				udelay = <0>;
				load = <0x42000000>;
				load_c = <0x45480000>;
			};
		};
	};
};
